input.new_string:
static int tflm_init(void)
{
  tflite::InitializeTarget();

  if (g_arena == nullptr)
    {
      g_arena = (uint8_t *)kmm_memalign(16, kArenaSize);
      if (g_arena == nullptr)
        {
          MicroPrintf("velapaw/tflm: arena alloc %d B failed", kArenaSize);
          return -1;
        }
    }

  g_model = tflite::GetModel(g_velapaw_model_data);

