/* The 1.4MB model is too large for flash-mapped rodata (the image's DROM
 * window bus-stalls past ~256KB). It's flashed to a raw offset and mapped at
 * runtime with esp32s3_mmap(), which allocates dedicated DROM0 MMU pages for
 * the whole region so GetModel() reads it straight from flash -- no copy, no
 * ROM spi_flash_read (that returns garbage without cache-safe setup).
 * struct + prototype mirror arch/xtensa/src/esp32s3/esp32s3_spiflash.h. */
struct spiflash_map_req_s
{
  uint32_t  src_addr;    /* flash offset to map        */
  uint32_t  size;        /* bytes to map               */
  void     *ptr;         /* [out] mapped pointer        */
  uint32_t  start_page;  /* [out] first MMU page index  */
  uint32_t  page_cnt;    /* [out] mapped page count     */
};
extern "C" int esp32s3_mmap(struct spiflash_map_req_s *req);
#define VELAPAW_MODEL_FLASH_OFFSET 0x600000u

