echo "=== Prepare: scratch request ==="; grep -nE 'RequestScratchBufferInArena|scratch_buf_size|get_conv_scratch|buffer_idx|Prepare' $W
echo "=== Eval: scratch use + esp_nn call ==="; sed -n '200,270p' $W
=== Prepare: scratch request ===
42:  int buffer_idx;
51:static TfLiteStatus Prepare(TfLiteContext* context, TfLiteNode* node) {
128:    context->RequestScratchBufferInArena(context, filter_size,
153:    int scratch_buf_size = esp_nn_get_conv_scratch_size(
155:    if (scratch_buf_size > 0) {
156:      TF_LITE_ENSURE_STATUS(context->RequestScratchBufferInArena(
157:        context, scratch_buf_size, &data->buffer_idx));
159:      data->buffer_idx = -1;
223:    if (data.buffer_idx > -1) {
224:      scratch_buf = context->GetScratchBuffer(context, data.buffer_idx);
410:  return tflite::micro::RegisterOp(Init, Prepare, Eval);
=== Eval: scratch use + esp_nn call ===
    const int filter_height = filter_shape.Dims(1);
    const int filter_width = filter_shape.Dims(2);
    const int output_height = output_shape.Dims(1);
    const int output_width = output_shape.Dims(2);

    // Set min and max value of the output.
    const int32_t activation_min = data.op_data.output_activation_min;
    const int32_t activation_max = data.op_data.output_activation_max;

    // Consistency check.
    TFLITE_DCHECK_LE(activation_min, activation_max);
    TFLITE_DCHECK_EQ(input_shape.DimensionsCount(), 4);
    TFLITE_DCHECK_EQ(filter_shape.DimensionsCount(), 4);
    TFLITE_DCHECK_EQ(output_shape.DimensionsCount(), 4);
    const int batch_size = MatchingDim(input_shape, 0, output_shape, 0);
    const int input_depth = MatchingDim(input_shape, 3, filter_shape, 3);
    const int output_depth = MatchingDim(filter_shape, 0, output_shape, 3);

    if (tflite::micro::GetTensorData<int8_t>(bias)) {
      TFLITE_DCHECK_EQ(bias_shape.FlatSize(), output_depth);
    }

    void *scratch_buf = NULL;
    if (data.buffer_idx > -1) {
      scratch_buf = context->GetScratchBuffer(context, data.buffer_idx);
    }
    esp_nn_set_conv_scratch_buf(scratch_buf);

    const int input_size = input_width * input_height * input_depth;
    const int output_size = output_width * output_height * output_depth;

    data_dims_t input_dims =  {
                                .width = input_width, .height = input_height,
                                .channels = input_depth, .extra = 1
                              };
    data_dims_t output_dims = {
                                .width = output_width, .height = output_height,
                                .channels = output_depth, .extra = 1
                              };
    data_dims_t filter_dims = {
                                .width = filter_width, .height = filter_height,
                                .channels = filter->dims->data[3], .extra = 0
                              };
    conv_params_t conv_params = {
                                  .in_offset = input_offset, .out_offset = output_offset,
                                  .stride = {stride_width, stride_height},
                                  .padding = {pad_width, pad_height},
                                  .dilation = {0, 0},
                                  .activation = {activation_min, activation_max}
                                };
    quant_data_t quant_data = {
                                .shift = data.op_data.per_channel_output_shift,
                                .mult = data.op_data.per_channel_output_multiplier
                              };

    for (int i_batch = 0; i_batch < batch_size; i_batch++) {
      esp_nn_conv_s8(&input_dims, input_data + i_batch * input_size,
                     &filter_dims, tflite::micro::GetTensorData<int8_t>(filter),
