206	static int tflm_embed(const struct velapaw_frame *frame, float *out, int dim)
207	{
208	  if (g_interp == nullptr || frame == nullptr || out == nullptr || dim <= 0)
209	    {
210	      return -1;
211	    }
212	
213	  /* Preprocess: RGB uint8 -> normalized [-1,1] -> int8 per model input quant
214	   * (matches host normalization mean/std = 127.5). */
215	  float in_scale = g_input->params.scale;
216	  int   in_zp    = g_input->params.zero_point;
217	  if (in_scale == 0.0f)
218	    {
219	      in_scale = 1.0f / 128.0f;   /* symmetric fallback */
220	    }
221	  int n    = frame->width * frame->height * frame->channels;
222	  int in_n = g_input->bytes;
223	  for (int i = 0; i < n && i < in_n; i++)
224	    {
225	      float norm = ((float)frame->data[i] - 127.5f) / 127.5f;
226	      int q = (int)lroundf(norm / in_scale) + in_zp;
227	      if (q < -128) q = -128;
228	      if (q > 127)  q = 127;
229	      g_input->data.int8[i] = (int8_t)q;
230	    }
231	
232	  static int _embed_call = 0;
233	  struct mallinfo _mi = mallinfo();
234	  printf("embed #%d: heap used=%d free=%d, invoke...\n",
235	         ++_embed_call, _mi.uordblks, _mi.fordblks); fflush(stdout);
236	  struct timespec t0;
237	  struct timespec t1;
238	  clock_gettime(CLOCK_MONOTONIC, &t0);
239	  TfLiteStatus status = g_interp->Invoke();
240	  clock_gettime(CLOCK_MONOTONIC, &t1);
241	  g_last_us = elapsed_us(&t0, &t1);
242	  printf("embed #%d: invoke ret=%d\n", _embed_call, (int)status); fflush(stdout);
243	
244	  if (status != kTfLiteOk)
245	    {
246	      MicroPrintf("velapaw/tflm: Invoke failed");
247	      return -1;
248	    }
249	
250	  /* Dequantize the output tensor into the embedding, zero-pad, L2-normalize.
251	   * (person_detect output is 2 values; a real embedding model fills `dim`.) */
252	  TfLiteTensor *o   = g_interp->output(0);
253	  float        scale = o->params.scale;
254	  int          zp    = o->params.zero_point;
255	  int          olen  = o->bytes;   /* int8 element count */
256	
257	  for (int i = 0; i < dim; i++)
258	    {
259	      out[i] = 0.0f;
260	    }
261	
262	  for (int i = 0; i < olen && i < dim; i++)
263	    {
264	      out[i] = ((int)o->data.int8[i] - zp) * scale;
265	    }
266	
267	  float norm = 0.0f;
268	  for (int i = 0; i < dim; i++)
269	    {
270	      norm += out[i] * out[i];
271	    }
272	
273	  norm = sqrtf(norm);
274	  if (norm < 1e-6f)
275	    {
276	      norm = 1.0f;
277	    }
278	
279	  for (int i = 0; i < dim; i++)
280	    {
281	      out[i] /= norm;
282	    }
283	
284	  return 0;
285	}
