#define VELAPAW_MODEL_SIZE 1436344u   /* infer/model/velapaw.tflite */

/* Read the 1.4MB model from raw flash 0x600000 into a PSRAM buffer, on a
 * pthread with an internal-RAM stack (spi_flash_read's on-stack SPI buffer
 * can't live in PSRAM while the read suspends the cache). */
static const tflite::Model *velapaw_load_model_from_flash(void)
{
  uint8_t *buf = (uint8_t *)kmm_memalign(16, VELAPAW_MODEL_SIZE);
  if (buf == nullptr)
    {
      printf("tflm: model PSRAM buf alloc %u B FAILED\n",
             (unsigned)VELAPAW_MODEL_SIZE); fflush(stdout);
      return nullptr;
    }
  struct velapaw_flash_rd r = { VELAPAW_MODEL_FLASH_OFFSET, buf,
                                VELAPAW_MODEL_SIZE, -1 };
  pthread_attr_t attr;
  pthread_t th;
  pthread_attr_init(&attr);
  pthread_attr_setstack(&attr, g_flash_rd_stack, sizeof(g_flash_rd_stack));
  printf("tflm: flash-read %u B from 0x%06x -> %p ...\n",
         (unsigned)VELAPAW_MODEL_SIZE, VELAPAW_MODEL_FLASH_OFFSET,
         (void *)buf); fflush(stdout);
  if (pthread_create(&th, &attr, velapaw_flash_rd_thread, &r) != 0)
    {
      printf("tflm: flash-read thread create FAILED\n"); fflush(stdout);
      pthread_attr_destroy(&attr);
      kmm_free(buf);
      return nullptr;
    }
  pthread_join(th, nullptr);
  pthread_attr_destroy(&attr);
  printf("tflm: flash-read rc=%d, model[0..3]=%02x %02x %02x %02x\n",
         r.rc, buf[0], buf[1], buf[2], buf[3]); fflush(stdout);
  if (r.rc < 0)
    {
      kmm_free(buf);
      return nullptr;
    }
  return tflite::GetModel(buf);
}

