      for (int i = 0; i < len; i++) SPI_SEND(spi, data[i]);
    }
  SPI_SELECT(spi, SPIDEV_DISPLAY(0), false);
}

static void st7796_init_and_fill(struct spi_dev_s *spi)
{
  static uint8_t line[LCD_W * 2];
  uint8_t caset[4] = {0x00,0x00,(LCD_W-1)>>8,(LCD_W-1)&0xff};
  uint8_t raset[4] = {0x00,0x00,(LCD_H-1)>>8,(LCD_H-1)&0xff};
  int i;
  SPI_LOCK(spi, true);
  SPI_SETMODE(spi, SPIDEV_MODE0);
  SPI_SETBITS(spi, 8);
  SPI_SETFREQUENCY(spi, 20000000);
  for (i = 0; i < (int)(sizeof(g_st7796_init)/sizeof(g_st7796_init[0])); i++)
    {
      st7796_wrcmd(spi, g_st7796_init[i].cmd, g_st7796_init[i].data, g_st7796_init[i].len);
      if (g_st7796_init[i].delayms) up_mdelay(g_st7796_init[i].delayms);
    }
  for (i = 0; i < LCD_W; i++) { line[2*i]=0x07; line[2*i+1]=0xE0; }
  st7796_wrcmd(spi, 0x2A, caset, 4);
  st7796_wrcmd(spi, 0x2B, raset, 4);
  SPI_SELECT(spi, SPIDEV_DISPLAY(0), true);
  SPI_CMDDATA(spi, SPIDEV_DISPLAY(0), true);
  SPI_SEND(spi, 0x2C);
  SPI_CMDDATA(spi, SPIDEV_DISPLAY(0), false);
  for (i = 0; i < LCD_H; i++) SPI_SNDBLOCK(spi, line, LCD_W * 2);
  SPI_SELECT(spi, SPIDEV_DISPLAY(0), false);
  SPI_LOCK(spi, false);
  syslog(LOG_ERR, "[wslcd] ST7796 init + green fill done\n");
  up_mdelay(1500);
}

int board_lcd_initialize(void)
{
  struct i2c_master_s *i2c;
  struct ioexpander_dev_s *ioe;
  int ret;
  syslog(LOG_ERR, "[wslcd] init start\n");
  esp32s3_configgpio(GPIO_LCD_BL, OUTPUT); esp32s3_gpiowrite(GPIO_LCD_BL, true);
  esp32s3_configgpio(GPIO_LCD_DC, OUTPUT); esp32s3_gpiowrite(GPIO_LCD_DC, true);
  i2c = esp32s3_i2cbus_initialize(LCD_I2C_PORTNO);
  if (i2c == NULL) { syslog(LOG_ERR, "[wslcd] I2C FAILED\n"); }
  else
    {
      ioe = pca9557_initialize(i2c, &g_tca9554);
      if (ioe == NULL) { syslog(LOG_ERR, "[wslcd] TCA9554 FAILED\n"); }
      else
        {
          ret  = IOEXP_SETDIRECTION(ioe, EXIO_PWR, IOEXPANDER_DIRECTION_OUT);
          ret |= IOEXP_SETDIRECTION(ioe, EXIO_LCD_RST, IOEXPANDER_DIRECTION_OUT);
          ret |= IOEXP_WRITEPIN(ioe, EXIO_PWR, false);
          ret |= IOEXP_WRITEPIN(ioe, EXIO_LCD_RST, false);
          nxsig_usleep(100000);
          ret |= IOEXP_WRITEPIN(ioe, EXIO_LCD_RST, true);
          nxsig_usleep(120000);
          syslog(LOG_ERR, "[wslcd] TCA9554 ok ret=%d\n", ret);
        }
    }
  g_spidev = esp32s3_spibus_initialize(LCD_SPI_PORTNO);
  if (g_spidev == NULL) { syslog(LOG_ERR, "[wslcd] SPI FAILED\n"); return -ENODEV; }
  syslog(LOG_ERR, "[wslcd] init done, SPI ok\n");
  return OK;
}

struct lcd_dev_s *board_lcd_getdev(int devno)
{
  g_lcd = st7789_lcdinitialize(g_spidev);
  syslog(LOG_ERR, "[wslcd] st7789_lcdinitialize -> %s\n", g_lcd ? "OK" : "NULL");
  if (g_spidev != NULL) st7796_init_and_fill(g_spidev);
  return g_lcd;
}

void board_lcd_uninitialize(void)
{
  if (g_lcd != NULL) g_lcd->setpower(g_lcd, 0);
}
EOF

