# add read helper before st7796_init_and_fill
helper='''static void st7796_read(struct spi_dev_s *spi, uint8_t cmd, uint8_t *buf, int n)
{
  int i;
  SPI_SELECT(spi, SPIDEV_DISPLAY(0), true);
  SPI_CMDDATA(spi, SPIDEV_DISPLAY(0), true);
  SPI_SEND(spi, cmd);
  SPI_CMDDATA(spi, SPIDEV_DISPLAY(0), false);
  for (i = 0; i < n; i++) buf[i] = (uint8_t)SPI_SEND(spi, 0xFF);
  SPI_SELECT(spi, SPIDEV_DISPLAY(0), false);
