  | xargs -r sed -i -E 's/(define[[:space:]]+LOCK_INITIALIZER_UNLOCKED[[:space:]]+)0[[:space:]]*$/\1SP_UNLOCKED/'
./build.sh esp32s3-devkit:waveshare_lcd -j4 2>&1 | tail -5
echo "=== BUILD EXIT ${PIPESTATUS[0]} ==="
grep -c "axp2101_power_lcd" nuttx/boards/xtensa/esp32s3/esp32s3-devkit/src/esp32s3_st7789.c
