#include <nuttx/config.h>
#include <stdint.h>
#include <stdbool.h>
#include <syslog.h>
#include <nuttx/arch.h>
#include <nuttx/signal.h>
#include <nuttx/i2c/i2c_master.h>
#include <nuttx/spi/spi.h>
#include <nuttx/lcd/lcd.h>
#include <nuttx/ioexpander/ioexpander.h>
#include <nuttx/ioexpander/pca9557.h>
#include "esp32s3_i2c.h"
#include "esp32s3_spi.h"
#include "esp32s3_gpio.h"

#define PIN_MOSI 1
#define PIN_CLK  5
#define PIN_DC   3
#define PIN_BL   6
#define XRES     480
#define YRES     320

static struct pca9557_config_s g_tca = { 0x20, 100000, NULL };

static int axp_wr(struct i2c_master_s *i2c, uint8_t r, uint8_t v)
{
  struct i2c_msg_s m; uint8_t b[2]; b[0]=r; b[1]=v;
  m.frequency=400000; m.addr=0x34; m.flags=0; m.buffer=b; m.length=2;
  return I2C_TRANSFER(i2c, &m, 1);
}
static void axp_power(struct i2c_master_s *i2c)
{
  axp_wr(i2c,0x80,0x01); axp_wr(i2c,0x82,(3300-1500)/100);
  axp_wr(i2c,0x90,0x00); axp_wr(i2c,0x91,0x00); nxsig_usleep(5000);
  axp_wr(i2c,0x92,(3300-500)/100); axp_wr(i2c,0x96,(1500-500)/100);
  axp_wr(i2c,0x97,(2800-500)/100); axp_wr(i2c,0x90,0x31); nxsig_usleep(120000);
}

/* ---- bit-bang (known good) : init panel + fill black ---- */
static void bbb(uint8_t b){int i;for(i=0;i<8;i++){esp32s3_gpiowrite(PIN_MOSI,(b&0x80)!=0);b<<=1;esp32s3_gpiowrite(PIN_CLK,true);esp32s3_gpiowrite(PIN_CLK,false);}}
static void bc(uint8_t c){esp32s3_gpiowrite(PIN_DC,false);bbb(c);}
static void bd(uint8_t d){esp32s3_gpiowrite(PIN_DC,true);bbb(d);}
static void bb_init_black(void)
{
  long n;
  esp32s3_configgpio(PIN_MOSI,OUTPUT); esp32s3_configgpio(PIN_CLK,OUTPUT); esp32s3_configgpio(PIN_DC,OUTPUT);
  esp32s3_gpiowrite(PIN_CLK,false);
  bc(0x01); up_mdelay(150); bc(0x11); up_mdelay(120);
  bc(0xF0); bd(0xC3); bc(0xF0); bd(0x96);
  bc(0x36); bd(0x28); bc(0x3A); bd(0x55);
  bc(0xF0); bd(0x3C); bc(0xF0); bd(0x69);
  bc(0x21); bc(0x29); up_mdelay(120);
  bc(0x2A); bd(0); bd(0); bd((XRES-1)>>8); bd((XRES-1)&0xff);
  bc(0x2B); bd(0); bd(0); bd((YRES-1)>>8); bd((YRES-1)&0xff);
  bc(0x2C); esp32s3_gpiowrite(PIN_DC,true);
  for (n=0;n<(long)XRES*YRES;n++){ bbb(0x00); bbb(0x00); }   /* black */
