static void axp_power(struct i2c_master_s *i){axp_wr(i,0x80,0x01);axp_wr(i,0x82,(3300-1500)/100);axp_wr(i,0x90,0x00);axp_wr(i,0x91,0x00);nxsig_usleep(5000);axp_wr(i,0x92,(3300-500)/100);axp_wr(i,0x96,(1500-500)/100);axp_wr(i,0x97,(2800-500)/100);axp_wr(i,0x90,0x31);nxsig_usleep(120000);}

/* slow, reliable — init commands */
static void bbb(uint8_t b){int i;for(i=0;i<8;i++){esp32s3_gpiowrite(PIN_MOSI,(b&0x80)!=0);b<<=1;esp32s3_gpiowrite(PIN_CLK,true);esp32s3_gpiowrite(PIN_CLK,false);}}
static void bc(uint8_t c){esp32s3_gpiowrite(PIN_DC,false);bbb(c);}
static void bd(uint8_t d){esp32s3_gpiowrite(PIN_DC,true);bbb(d);}

/* fast register writes + small setup delay — pixel data */
static inline void dly(void){ __asm__ volatile("nop\n nop\n nop\n nop"); }
static inline void ffbyte(uint8_t b)
{
  int i;
  for (i = 0; i < 8; i++)
    {
      if (b & 0x80) wreg(REG_W1TS, MOSI_M); else wreg(REG_W1TC, MOSI_M);
      b <<= 1;
      dly();
      wreg(REG_W1TS, CLK_M);
      dly();
      wreg(REG_W1TC, CLK_M);
    }
}

static void panel(void)
{
  static const uint16_t bars[8]={0xF800,0x07E0,0x001F,0xFFE0,0x07FF,0xF81F,0xFFFF,0x0000};
  clock_t t0,t1; int x,y; uint16_t c; uint8_t hi,lo;
  esp32s3_configgpio(PIN_MOSI,OUTPUT);esp32s3_configgpio(PIN_CLK,OUTPUT);esp32s3_configgpio(PIN_DC,OUTPUT);
  esp32s3_gpiowrite(PIN_CLK,false);
