      IOEXP_WRITEPIN(ioe,1,true);nxsig_usleep(120000);}}
  panel();
  return OK;
}
struct lcd_dev_s *board_lcd_getdev(int devno){return NULL;}
void board_lcd_uninitialize(void){}
