Now the driver. Paste in the VM (`Ctrl-C` server):

```bash
export PATH=$HOME/bin:$HOME/openvela/prebuilts/gcc/linux-x86_64/xtensa-esp32s3-elf/bin:$HOME/.local/bin:$PATH
cat > ~/openvela/nuttx/boards/xtensa/esp32s3/esp32s3-devkit/src/esp32s3_st7789.c <<'EOF'
/* Waveshare ESP32-S3-Touch-LCD-3.5: ST7796 lcd_dev over fast bit-bang. */
#include <nuttx/config.h>
#include <stdint.h>
#include <stdbool.h>
#include <errno.h>
#include <syslog.h>
#include <nuttx/arch.h>
#include <nuttx/signal.h>
#include <nuttx/i2c/i2c_master.h>
#include <nuttx/video/fb.h>
#include <nuttx/lcd/lcd.h>
#include <nuttx/ioexpander/ioexpander.h>
#include <nuttx/ioexpander/pca9557.h>
#include "esp32s3_i2c.h"
#include "esp32s3_gpio.h"

#define PIN_MOSI 1
#define PIN_CLK  5
#define PIN_DC   3
#define PIN_BL   6
#define XRES 480
#define YRES 320
#define MOSI_M (1U << PIN_MOSI)
#define CLK_M  (1U << PIN_CLK)
#define REG_W1TS 0x60004008U
#define REG_OUT  0x60004004U
static inline void wreg(uint32_t a, uint32_t v){ *(volatile uint32_t *)a = v; }

struct wslcd_s { struct lcd_dev_s dev; int power; uint16_t runbuf[XRES]; };
static struct wslcd_s g_lcd;
static struct pca9557_config_s g_tca = { 0x20, 100000, NULL };

static int axp_wr(struct i2c_master_s *i,uint8_t r,uint8_t v){struct i2c_msg_s m;uint8_t b[2];b[0]=r;b[1]=v;m.frequency=400000;m.addr=0x34;m.flags=0;m.buffer=b;m.length=2;return I2C_TRANSFER(i,&m,1);}
static void axp_power(struct i2c_master_s *i){axp_wr(i,0x80,0x01);axp_wr(i,0x82,(3300-1500)/100);axp_wr(i,0x90,0x00);axp_wr(i,0x91,0x00);nxsig_usleep(5000);axp_wr(i,0x92,(3300-500)/100);axp_wr(i,0x96,(1500-500)/100);axp_wr(i,0x97,(2800-500)/100);axp_wr(i,0x90,0x31);nxsig_usleep(120000);}

/* --- bit-bang transport --- */
static void bbb(uint8_t b){int i;for(i=0;i<8;i++){esp32s3_gpiowrite(PIN_MOSI,(b&0x80)!=0);b<<=1;esp32s3_gpiowrite(PIN_CLK,true);esp32s3_gpiowrite(PIN_CLK,false);}}
static void bc(uint8_t c){esp32s3_gpiowrite(PIN_DC,false);bbb(c);}
static void bd(uint8_t d){esp32s3_gpiowrite(PIN_DC,true);bbb(d);}
static inline void ffbyte(uint8_t b, uint32_t base){int i;for(i=0;i<8;i++){uint32_t o=base|((b&0x80)?MOSI_M:0);b<<=1;wreg(REG_OUT,o);wreg(REG_OUT,o|CLK_M);}}
static void bb_window(int x0,int x1,int y0,int y1){bc(0x2A);bd(x0>>8);bd(x0&0xff);bd(x1>>8);bd(x1&0xff);bc(0x2B);bd(y0>>8);bd(y0&0xff);bd(y1>>8);bd(y1&0xff);bc(0x2C);esp32s3_gpiowrite(PIN_DC,true);}

static void panel_init(void)
{
  esp32s3_configgpio(PIN_MOSI,OUTPUT);esp32s3_configgpio(PIN_CLK,OUTPUT);esp32s3_configgpio(PIN_DC,OUTPUT);
  esp32s3_gpiowrite(PIN_CLK,false);
  bc(0x01);up_mdelay(150);bc(0x11);up_mdelay(120);
  bc(0xF0);bd(0xC3);bc(0xF0);bd(0x96);bc(0x36);bd(0x28);bc(0x3A);bd(0x55);
  bc(0xF0);bd(0x3C);bc(0xF0);bd(0x69);bc(0x21);bc(0x29);up_mdelay(120);
  /* clear to black */
  {long n; uint32_t base; bb_window(0,XRES-1,0,YRES-1);
   base=(*(volatile uint32_t*)REG_OUT)&~(MOSI_M|CLK_M);
   for(n=0;n<(long)XRES*YRES;n++){ffbyte(0,base);ffbyte(0,base);}}
  syslog(LOG_ERR,"[wslcd] panel_init done (lcd_dev ready)\n");
}

/* --- lcd_dev ops --- */
static int lcd_getvideoinfo(struct lcd_dev_s *dev, struct fb_videoinfo_s *vinfo)
{ vinfo->fmt=FB_FMT_RGB16_565; vinfo->xres=XRES; vinfo->yres=YRES; vinfo->nplanes=1; return OK; }

static int lcd_putrun(struct lcd_dev_s *dev, fb_coord_t row, fb_coord_t col, const uint8_t *buffer, size_t npixels)
{
  uint32_t base; size_t i;
  bb_window(col, col+npixels-1, row, row);
  base=(*(volatile uint32_t*)REG_OUT)&~(MOSI_M|CLK_M);
  for(i=0;i<npixels*2;i++) ffbyte(buffer[i], base);
  return OK;
}

static int lcd_putarea(struct lcd_dev_s *dev, fb_coord_t rs, fb_coord_t re, fb_coord_t cs, fb_coord_t ce, const uint8_t *buffer, fb_coord_t stride)
{
  uint32_t base; int rows=re-rs+1, r; size_t rowb=(size_t)(ce-cs+1)*2, i;
  bb_window(cs, ce, rs, re);
  base=(*(volatile uint32_t*)REG_OUT)&~(MOSI_M|CLK_M);
  for(r=0;r<rows;r++){const uint8_t *p=buffer+(size_t)r*stride; for(i=0;i<rowb;i++) ffbyte(p[i], base);}
  return OK;
}

#ifndef CONFIG_LCD_NOGETRUN
static int lcd_getrun(struct lcd_dev_s *dev, fb_coord_t row, fb_coord_t col, uint8_t *buffer, size_t npixels)
{ return -ENOSYS; }   /* write-only panel (no MISO) */
#endif

static int lcd_getplaneinfo(struct lcd_dev_s *dev, unsigned int planeno, struct lcd_planeinfo_s *pinfo)
{
  pinfo->putrun=lcd_putrun; pinfo->putarea=lcd_putarea;
#ifndef CONFIG_LCD_NOGETRUN
  pinfo->getrun=lcd_getrun;
#endif
  pinfo->buffer=(uint8_t *)g_lcd.runbuf; pinfo->bpp=16; pinfo->dev=dev; return OK;
}

static int lcd_getpower(struct lcd_dev_s *dev){ return g_lcd.power; }
static int lcd_setpower(struct lcd_dev_s *dev, int power){ g_lcd.power=power; esp32s3_gpiowrite(PIN_BL, power>0); return OK; }

int board_lcd_initialize(void)
{
  struct i2c_master_s *i2c; struct ioexpander_dev_s *ioe;
  syslog(LOG_ERR,"[wslcd] init\n");
  esp32s3_configgpio(PIN_BL,OUTPUT);esp32s3_gpiowrite(PIN_BL,true);
  i2c=esp32s3_i2cbus_initialize(0);
  if(i2c){axp_power(i2c);ioe=pca9557_initialize(i2c,&g_tca);
    if(ioe){IOEXP_SETDIRECTION(ioe,0,IOEXPANDER_DIRECTION_OUT);IOEXP_SETDIRECTION(ioe,1,IOEXPANDER_DIRECTION_OUT);
      IOEXP_WRITEPIN(ioe,0,false);IOEXP_WRITEPIN(ioe,1,false);nxsig_usleep(100000);
      IOEXP_WRITEPIN(ioe,1,true);nxsig_usleep(120000);}}
  panel_init();
  g_lcd.dev.getvideoinfo=lcd_getvideoinfo;
  g_lcd.dev.getplaneinfo=lcd_getplaneinfo;
  g_lcd.dev.getpower=lcd_getpower;
  g_lcd.dev.setpower=lcd_setpower;
  g_lcd.power=1;
  return OK;
}
struct lcd_dev_s *board_lcd_getdev(int devno){ return &g_lcd.dev; }
void board_lcd_uninitialize(void){}
EOF

