193	/****************************************************************************
194	 * frame display
195	 ****************************************************************************/
196	
197	static void frame_to_565(const struct velapaw_frame *f, uint16_t *dst)
198	{
199	  int npx = f->width * f->height;
200	  for (int i = 0; i < npx; i++)
201	    {
202	      uint8_t r = f->data[i * 3 + 0];
203	      uint8_t g = f->data[i * 3 + 1];
204	      uint8_t b = f->data[i * 3 + 2];
205	      dst[i] = (uint16_t)(((r & 0xF8) << 8) | ((g & 0xFC) << 3) | (b >> 3));
206	    }
207	}
208	
209	static void show_frame(const struct velapaw_frame *f)
210	{
211	  frame_to_565(f, g_img565);
212	  if (g_img)
213	    {
214	      lv_obj_invalidate(g_img);
215	    }
216	  if (g_img_r)
217	    {
218	      lv_obj_invalidate(g_img_r);
219	    }
220	}
