222	/****************************************************************************
223	 * appetite / alert  (relative to each pet's DAILY LIMIT = the ration the
224	 * owner set, not a rolling average)
225	 ****************************************************************************/
226	
227	/* % of today's ration eaten: today / daily_limit (0..100, since feeding stops
228	 * at the limit). 100% = ate its full daily allowance. */
229	static int pet_appetite_pct(velapaw_pet_id_t id, const struct velapaw_pet *p)
230	{
231	  int today = velapaw_store_today_total(id);
232	  int pct = (p->daily_limit_g > 0) ? today * 100 / p->daily_limit_g : 100;
233	  return (pct > 100) ? 100 : pct;   /* limit is a cap: never over 100% */
234	}
235	
236	/* appetite-drop alert: the last completed day was under half the daily limit. */
237	static int pet_alert_drop(velapaw_pet_id_t id, const struct velapaw_pet *p)
238	{
239	  int yesterday = velapaw_store_day_total(id, 1);
240	  return (p->daily_limit_g > 0 && yesterday * 2 < p->daily_limit_g) ? 1 : 0;
241	}
