391	static void do_save(void)
392	{
393	  if (g_nsamp == 0)
394	    {
395	      lv_label_set_text(g_sample_lbl, "capture at least 1 sample");
396	      return;
397	    }
398	  char name[VELAPAW_NAME_MAX];
399	  const char *typed = lv_textarea_get_text(g_name_ta);
400	  if (typed && typed[0] != '\0')
401	    {
402	      strncpy(name, typed, sizeof(name) - 1);
403	      name[sizeof(name) - 1] = '\0';
404	    }
405	  else
406	    {
407	      snprintf(name, sizeof(name), "Pet %d", g_petn + 1);
408	    }
409	  int portion = (int)lv_slider_get_value(g_portion_slider);
410	  int limit   = (int)lv_slider_get_value(g_limit_slider);
411	  if (limit < portion)
412	    {
413	      limit = portion;   /* never below one serving */
414	    }
415	  velapaw_pet_id_t id = velapaw_identity_enroll(name, portion,
416	                                                UI_DEMO_COOLDOWN_S, limit,
417	                                                g_samples, g_nsamp);
418	  printf("velapaw/ui: saved %s (id %d) %dg from %d samples\n",
419	         name, id, portion, g_nsamp);
420	  velapaw_store_seed(id, portion * 3);   /* baseline ~3 meals/day for trends */
421	  g_petn++;
422	  g_nsamp = 0;
423	  lv_textarea_set_text(g_name_ta, "");
424	  refresh_enroll();
425	  refresh_pets();
426	  lv_label_set_text_fmt(g_count, "enrolled pets: %d", velapaw_identity_count());
427	
428	  char msg[96];
429	  snprintf(msg, sizeof(msg),
430	           "%s enrolled. The feeder can now recognize this pet.", name);
431	  show_enroll_popup(msg);
432	}
