816	static void refresh_trends(void)
817	{
818	  if (g_trend_chart == NULL)
819	    {
820	      return;
821	    }
822	  int cnt = velapaw_identity_count();
823	  if (cnt == 0)
824	    {
825	      lv_label_set_text(g_trend_title, "Trends - enroll a pet first");
826	      lv_label_set_text(g_trend_stats, "");
827	      lv_label_set_text(g_trend_val, "");
828	      return;
829	    }
830	  if (g_trend_pet >= cnt)
831	    {
832	      g_trend_pet = 0;
833	    }
834	  const struct velapaw_pet *pet = velapaw_identity_get(g_trend_pet);
835	  int n = g_trend_month ? VELAPAW_HIST_DAYS : VELAPAW_WEEK_DAYS;
836	  lv_chart_set_point_count(g_trend_chart, n);
837	  int maxg = 1;
838	  for (int i = 0; i < n; i++)
839	    {
840	      int db = (n - 1) - i;              /* i=0 oldest ... i=n-1 today */
841	      int v = velapaw_store_day_total(g_trend_pet, db);
842	      g_trend_vals[i] = v;
843	      if (v > maxg)
844	        {
845	          maxg = v;
846	        }
847	    }
848	  lv_chart_set_range(g_trend_chart, LV_CHART_AXIS_PRIMARY_Y, 0, maxg);
849	  for (int i = 0; i < n; i++)
850	    {
851	      lv_chart_set_value_by_id(g_trend_chart, g_trend_ser, i, g_trend_vals[i]);
852	    }
853	  lv_chart_refresh(g_trend_chart);
854	
855	  lv_label_set_text_fmt(g_trend_title, "Trends: %s  (%s)", pet->name,
856	                        g_trend_month ? "30-day" : "7-day");
857	  lv_label_set_text_fmt(g_trend_stats,
858	      "Today %d/%dg   Avg %dg/day\nWeek %dg   Month %dg   Appetite %d%%",
859	      velapaw_store_today_total(g_trend_pet), pet->daily_limit_g,
860	      velapaw_store_baseline_g(g_trend_pet),
861	      velapaw_store_week_total(g_trend_pet),
862	      velapaw_store_month_total(g_trend_pet),
863	      pet_appetite_pct(g_trend_pet, pet));
864	  lv_label_set_text(g_trend_val, "tap a bar to read its value");
865	
866	  /* highlight the active window toggle */
867	  if (g_btn_week && g_btn_month)
868	    {
869	      lv_obj_set_style_bg_color(g_btn_week,
870	          lv_color_hex(g_trend_month ? COL_BTN : COL_ACCENT), 0);
871	      lv_obj_set_style_bg_color(g_btn_month,
872	          lv_color_hex(g_trend_month ? COL_ACCENT : COL_BTN), 0);
873	    }
874	}
