932	void velapaw_ui_run(void)
933	{
934	  lv_nuttx_dsc_t info;
935	  lv_nuttx_result_t result;
936	
937	  lv_init();
938	  lv_nuttx_dsc_init(&info);
939	  lv_nuttx_init(&info, &result);
940	  if (result.disp == NULL)
941	    {
942	      printf("velapaw/ui: LVGL display init failed\n");
943	      return;
944	    }
945	  printf("velapaw/ui: LVGL ready; touch indev %s\n",
946	         result.indev ? "ok" : "MISSING");
947	
948	  lv_obj_t *scr = lv_screen_active();
