958	
959	  /* portrait column centered on the landscape screen */
960	  lv_obj_t *col = lv_obj_create(scr);
961	  lv_obj_set_size(col, COL_W, 800);
962	  lv_obj_align(col, LV_ALIGN_CENTER, 0, 0);
