19	esp_err_t xclk_timer_conf(int ledc_timer, int xclk_freq_hz)
20	{
21	    ledc_timer_config_t timer_conf;
22	    timer_conf.duty_resolution = LEDC_TIMER_1_BIT;
23	    timer_conf.freq_hz = xclk_freq_hz;
24	    timer_conf.speed_mode = LEDC_LOW_SPEED_MODE;
25	
26	#if ESP_IDF_VERSION >= ESP_IDF_VERSION_VAL(5, 2, 0)   
27	    timer_conf.deconfigure = false;
28	#endif
29	   
30	#if ESP_IDF_VERSION_MAJOR >= 4
31	    timer_conf.clk_cfg = LEDC_AUTO_CLK;
32	#endif
33	    timer_conf.timer_num = (ledc_timer_t)ledc_timer;
34	    esp_err_t err = ledc_timer_config(&timer_conf);
35	    if (err != ESP_OK) {
36	        ESP_LOGE(TAG, "ledc_timer_config failed for freq %d, rc=%x", xclk_freq_hz, err);
37	    }
38	    return err;
39	}
