44	    if (err != ESP_OK) {
45	        ESP_LOGE(TAG, "ledc_timer_config failed, rc=%x", err);
46	        return err;
47	    }
48	
49	    g_ledc_channel = config->ledc_channel;
50	    ledc_channel_config_t ch_conf = {0};
