53	    ch_conf.channel = config->ledc_channel;
54	#if ESP_IDF_VERSION < ESP_IDF_VERSION_VAL(6,0,0)  
55	    // no need to explicitly configure interrupt, handled in the driver (IDF v6.0 and above)
56	    ch_conf.intr_type = LEDC_INTR_DISABLE; 
57	#endif
58	    ch_conf.timer_sel = config->ledc_timer;
