60	    ch_conf.hpoint = 0;
61	    err = ledc_channel_config(&ch_conf);
62	    if (err != ESP_OK) {
63	        ESP_LOGE(TAG, "ledc_channel_config failed, rc=%x", err);
64	        return err;
65	    }
66	    return ESP_OK;
67	}
