557	size_t IRAM_ATTR ll_cam_memcpy(cam_obj_t *cam, uint8_t *out, const uint8_t *in, size_t len)
558	{
559	    // YUV to Grayscale
560	    if (cam->in_bytes_per_pixel == 2 && cam->fb_bytes_per_pixel == 1) {
561	        size_t end = len / 8;
562	        for (size_t i = 0; i < end; ++i) {
563	            out[0] = in[0];
564	            out[1] = in[2];
565	            out[2] = in[4];
566	            out[3] = in[6];
567	            out += 4;
568	            in += 8;
569	        }
570	        return len / 2;
571	    }
572	
573	    // just memcpy
574	    memcpy(out, in, len);
575	    return len;
576	}
