204	static int set_pll(sensor_t *sensor, bool bypass, uint8_t multiplier, uint8_t sys_div, uint8_t pre_div, bool root_2x, uint8_t pclk_root_div, bool pclk_manual, uint8_t pclk_div){
205	    int ret = 0;
206	    if(multiplier > 252 || multiplier < 4 || sys_div > 15 || pre_div > 8 || pclk_div > 31 || pclk_root_div > 3){
207	        ESP_LOGE(TAG, "Invalid arguments");
208	        return -1;
209	    }
210	    if(multiplier > 127){
211	        multiplier &= 0xFE;//only even integers above 127
212	    }
213	    ESP_LOGI(TAG, "Set PLL: bypass: %u, multiplier: %u, sys_div: %u, pre_div: %u, root_2x: %u, pclk_root_div: %u, pclk_manual: %u, pclk_div: %u", bypass, multiplier, sys_div, pre_div, root_2x, pclk_root_div, pclk_manual, pclk_div);
214	
215	    calc_sysclk(sensor->xclk_freq_hz, bypass, multiplier, sys_div, pre_div, root_2x, pclk_root_div, pclk_manual, pclk_div);
216	
217	    ret = write_reg(sensor->slv_addr, 0x3039, bypass?0x80:0x00);
218	    if (ret == 0) {
219	        ret = write_reg(sensor->slv_addr, 0x3034, 0x1A);//10bit mode
220	    }
221	    if (ret == 0) {
222	        ret = write_reg(sensor->slv_addr, 0x3035, 0x01 | ((sys_div & 0x0f) << 4));
223	    }
224	    if (ret == 0) {
225	        ret = write_reg(sensor->slv_addr, 0x3036, multiplier & 0xff);
226	    }
227	    if (ret == 0) {
228	        ret = write_reg(sensor->slv_addr, 0x3037, (pre_div & 0xf) | (root_2x?0x10:0x00));
229	    }
230	    if (ret == 0) {
231	        ret = write_reg(sensor->slv_addr, 0x3108, (pclk_root_div & 0x3) << 4 | 0x06);
232	    }
233	    if (ret == 0) {
234	        ret = write_reg(sensor->slv_addr, 0x3824, pclk_div & 0x1f);
235	    }
236	    if (ret == 0) {
237	        ret = write_reg(sensor->slv_addr, 0x460C, pclk_manual?0x22:0x20);
238	    }
239	    if (ret == 0) {
240	        ret = write_reg(sensor->slv_addr, 0x3103, 0x13);// system clock from pll, bit[1]
241	    }
242	    if(ret){
243	        ESP_LOGE(TAG, "set_sensor_pll FAILED!");
244	    }
245	    return ret;
246	}
