312	static int set_image_options(sensor_t *sensor)
313	{
314	    int ret = 0;
315	    uint8_t reg20 = 0;
316	    uint8_t reg21 = 0;
317	    uint8_t reg4514 = 0;
318	    uint8_t reg4514_test = 0;
319	
320	    // compression
321	    if (sensor->pixformat == PIXFORMAT_JPEG) {
322	        reg21 |= 0x20;
323	    }
324	
325	    // binning
326	    if (!sensor->status.binning) {
327	        reg20 |= 0x40;
328	    } else {
329	        reg20 |= 0x01;
330	        reg21 |= 0x01;
331	        reg4514_test |= 4;
332	    }
333	
334	    // V-Flip
335	    if (sensor->status.vflip) {
336	        reg20 |= 0x06;
337	        reg4514_test |= 1;
338	    }
339	
340	    // H-Mirror
341	    if (sensor->status.hmirror) {
342	        reg21 |= 0x06;
343	        reg4514_test |= 2;
344	    }
345	
346	    switch (reg4514_test) {
347	        //no binning
348	        case 0: reg4514 = 0x88; break;//normal
349	        case 1: reg4514 = 0x00; break;//v-flip
350	        case 2: reg4514 = 0xbb; break;//h-mirror
351	        case 3: reg4514 = 0x00; break;//v-flip+h-mirror
352	        //binning
353	        case 4: reg4514 = 0xaa; break;//normal
354	        case 5: reg4514 = 0xbb; break;//v-flip
355	        case 6: reg4514 = 0xbb; break;//h-mirror
356	        case 7: reg4514 = 0xaa; break;//v-flip+h-mirror
357	    }
358	
359	    if(write_reg(sensor->slv_addr, TIMING_TC_REG20, reg20)
360	        || write_reg(sensor->slv_addr, TIMING_TC_REG21, reg21)
361	        || write_reg(sensor->slv_addr, 0x4514, reg4514)){
362	        ESP_LOGE(TAG, "Setting Image Options Failed");
363	        return -1;
364	    }
365	
366	    if (!sensor->status.binning) {
367	        ret  = write_reg(sensor->slv_addr, 0x4520, 0x10)
368	            || write_reg(sensor->slv_addr, X_INCREMENT, 0x11)//odd:1, even: 1
369	            || write_reg(sensor->slv_addr, Y_INCREMENT, 0x11);//odd:1, even: 1
370	    } else {
371	        ret  = write_reg(sensor->slv_addr, 0x4520, 0x0b)
372	            || write_reg(sensor->slv_addr, X_INCREMENT, 0x31)//odd:3, even: 1
373	            || write_reg(sensor->slv_addr, Y_INCREMENT, 0x31);//odd:3, even: 1
374	    }
375	
376	    ESP_LOGD(TAG, "Set Image Options: Compression: %u, Binning: %u, V-Flip: %u, H-Mirror: %u, Reg-4514: 0x%02x",
