153	static int tflm_embed(const struct velapaw_frame *frame, float *out, int dim)
154	{
155	  if (g_interp == nullptr || frame == nullptr || out == nullptr || dim <= 0)
156	    {
157	      return -1;
158	    }
159	
160	  /* Preprocess: RGB uint8 -> normalized [-1,1] -> int8 per model input quant
161	   * (matches host normalization mean/std = 127.5). */
162	  float in_scale = g_input->params.scale;
163	  int   in_zp    = g_input->params.zero_point;
164	  if (in_scale == 0.0f)
165	    {
166	      in_scale = 1.0f / 128.0f;   /* symmetric fallback */
167	    }
168	  int n    = frame->width * frame->height * frame->channels;
169	  int in_n = g_input->bytes;
170	  for (int i = 0; i < n && i < in_n; i++)
171	    {
172	      float norm = ((float)frame->data[i] - 127.5f) / 127.5f;
173	      int q = (int)lroundf(norm / in_scale) + in_zp;
174	      if (q < -128) q = -128;
175	      if (q > 127)  q = 127;
176	      g_input->data.int8[i] = (int8_t)q;
177	    }
178	
179	  struct timespec t0;
180	  struct timespec t1;
181	  clock_gettime(CLOCK_MONOTONIC, &t0);
182	  TfLiteStatus status = g_interp->Invoke();
183	  clock_gettime(CLOCK_MONOTONIC, &t1);
184	  g_last_us = elapsed_us(&t0, &t1);
185	
186	  if (status != kTfLiteOk)
187	    {
188	      MicroPrintf("velapaw/tflm: Invoke failed");
189	      return -1;
190	    }
191	
192	  /* Dequantize the output tensor into the embedding, zero-pad, L2-normalize.
193	   * (person_detect output is 2 values; a real embedding model fills `dim`.) */
194	  TfLiteTensor *o   = g_interp->output(0);
195	  float        scale = o->params.scale;
196	  int          zp    = o->params.zero_point;
197	  int          olen  = o->bytes;   /* int8 element count */
198	
199	  for (int i = 0; i < dim; i++)
200	    {
201	      out[i] = 0.0f;
202	    }
203	
204	  for (int i = 0; i < olen && i < dim; i++)
205	    {
206	      out[i] = ((int)o->data.int8[i] - zp) * scale;
207	    }
208	
209	  float norm = 0.0f;
210	  for (int i = 0; i < dim; i++)
211	    {
212	      norm += out[i] * out[i];
213	    }
214	
215	  norm = sqrtf(norm);
216	  if (norm < 1e-6f)
217	    {
218	      norm = 1.0f;
219	    }
220	
221	  for (int i = 0; i < dim; i++)
222	    {
223	      out[i] /= norm;
224	    }
225	
226	  return 0;
227	}
