261	
262	  if (g_bcs_interp->Invoke() != kTfLiteOk)
263	    {
264	      return -1;
265	    }
266	
267	  TfLiteTensor *o = g_bcs_interp->output(0);
268	  float scale = o->params.scale;
269	  int   zp    = o->params.zero_point;
270	  int   best  = 0;
271	  float bestp = -1.0f;
272	  for (int i = 0; i < o->bytes; i++)
273	    {
274	      float p = ((int)o->data.uint8[i] - zp) * scale;
275	      if (p > bestp)
