Now I see it clearly — and it's the **same root cause** as the elementwise errors, not a version bug: the lambdas do `[](float v){ return std::exp(v); }`, but `std::exp(float)` returns **`double`** (NuttX's `<cmath>` has no float overloads), so the lambda is `double(*)(float)` and matches **no** `LUTPopulate` overload (all want `float(*)(float)`). `-fpermissive` can't fix overload *resolution*.

The clean structural fix that kills this whole class at once: **add the missing `std::` float overloads** via a force-included shim header, so `std::exp(float)→float`, `std::sqrt(float)→float`, etc. Then every one of these lambdas resolves correctly. Paste in the VM:

```bash
TFDIR=~/openvela/apps/mlearning/tflite-micro
cat > $TFDIR/float_shim.h <<'EOF'
#ifndef VELAPAW_FLOAT_SHIM_H
#define VELAPAW_FLOAT_SHIM_H
#include <math.h>
namespace std {
  inline float exp(float x){return expf(x);}
  inline float sqrt(float x){return sqrtf(x);}
  inline float log(float x){return logf(x);}
  inline float log2(float x){return log2f(x);}
  inline float sin(float x){return sinf(x);}
  inline float cos(float x){return cosf(x);}
  inline float tanh(float x){return tanhf(x);}
  inline float round(float x){return roundf(x);}
  inline float floor(float x){return floorf(x);}
  inline float ceil(float x){return ceilf(x);}
  inline float fabs(float x){return fabsf(x);}
  inline float pow(float a,float b){return powf(a,b);}
  inline float fmax(float a,float b){return fmaxf(a,b);}
  inline float fmin(float a,float b){return fminf(a,b);}
  inline float fmod(float a,float b){return fmodf(a,b);}
  inline float expm1(float x){return expm1f(x);}
}
#endif
EOF
