/* The 1.4MB model can't live in flash-mapped rodata (the esp32s3 DROM map
 * window is < 256KB, so reads past it bus-stall). Instead the .tflite is
 * flashed to a raw offset and read into a PSRAM buffer at runtime via the
 * flash driver (bypasses the memory-map). */
extern "C" int spi_flash_read(uint32_t addr, void *buffer, uint32_t size);
#define VELAPAW_MODEL_FLASH_OFFSET 0x600000u

