/* Read the model from raw flash (@VELAPAW_MODEL_FLASH_OFFSET) into a PSRAM
 * buffer via the flash driver -- this reads the real flash bytes rather than
 * going through the tiny DROM memory-map window that stalls past ~256KB. */
static uint8_t *model_buf = nullptr;
if (model_buf == nullptr)
  {
    uint32_t model_len = (uint32_t)g_velapaw_model_data_size;
    model_buf = (uint8_t *)kmm_memalign(16, model_len);
    printf("tflm: model_buf=%p, spi_flash_read @0x%06x len=%u...\n",
           (void *)model_buf, VELAPAW_MODEL_FLASH_OFFSET,
           (unsigned)model_len); fflush(stdout);
    if (model_buf == nullptr)
      {
        MicroPrintf("velapaw/tflm: model buf alloc %u B failed", model_len);
        return -1;
      }
    int _fr = spi_flash_read(VELAPAW_MODEL_FLASH_OFFSET, model_buf, model_len);
    printf("tflm: flash read ret=%d, buf[0..7]=%02x %02x %02x %02x %02x %02x %02x %02x\n",
           _fr, model_buf[0], model_buf[1], model_buf[2], model_buf[3],
           model_buf[4], model_buf[5], model_buf[6], model_buf[7]);
    fflush(stdout);
  }
g_model = tflite::GetModel(model_buf);
printf("tflm: model version=%u\n", (unsigned)g_model->version()); fflush(stdout);

