/* Copy the model from raw flash into a PSRAM buffer, chunk by chunk through
 * an internal-RAM bounce buffer (ROM read suspends the cache -> dest must be
 * internal RAM; between chunks the cache is live so the PSRAM copy works). */
static uint8_t *model_buf = nullptr;
if (model_buf == nullptr)
  {
    uint32_t len = (uint32_t)g_velapaw_model_data_size;
    model_buf = (uint8_t *)kmm_memalign(16, len);   /* PSRAM */
    if (model_buf == nullptr)
      {
        MicroPrintf("velapaw/tflm: model buf alloc %u B failed", len);
        return -1;
      }
    static uint8_t bounce[16384];                   /* internal RAM (.bss) */
    printf("tflm: load model flash@0x%06x len=%u (chunked)...\n",
           VELAPAW_MODEL_FLASH_OFFSET, (unsigned)len); fflush(stdout);
    uint32_t off = 0;
    int rc = 0;
    while (off < len)
      {
        uint32_t n = len - off;
        if (n > sizeof(bounce)) n = sizeof(bounce);
        rc = spi_flash_read(VELAPAW_MODEL_FLASH_OFFSET + off, bounce, n);
        if (rc != 0) break;
        memcpy(model_buf + off, bounce, n);
        off += n;
      }
    printf("tflm: flash load rc=%d %u/%u B, buf[0..7]=%02x %02x %02x %02x %02x %02x %02x %02x (want ..54 46 4c 33)\n",
           rc, (unsigned)off, (unsigned)len,
           model_buf[0], model_buf[1], model_buf[2], model_buf[3],
           model_buf[4], model_buf[5], model_buf[6], model_buf[7]);
    fflush(stdout);
    if (off < len)
      {
        MicroPrintf("velapaw/tflm: flash load failed at %u", off);
        return -1;
      }
  }
g_model = tflite::GetModel(model_buf);
printf("tflm: model version=%u\n", (unsigned)g_model->version()); fflush(stdout);

