/* The 1.4MB model is too large for flash-mapped rodata (the image's DROM
 * window bus-stalls past ~256KB). It's flashed to a raw offset and copied into
 * a PSRAM buffer at runtime with the ROM spi_flash_read, staged through a small
 * internal-RAM bounce buffer. The ROM read suspends the data cache, so its
 * destination MUST be internal RAM -- reading directly into PSRAM (cache-backed)
 * returns garbage. Between chunks the cache is live, so the PSRAM copy is fine.
 * Uses the NuttX software SPI-flash read (esp32s3_spiflash.c, enabled by
 * CONFIG_ESP32S3_SPI_FLASH_DONT_USE_ROM_CODE): it reads via the SPI peripheral
 * (no MMU -> no -ENOBUFS; no ROM -> no err 24577) and internally toggles the
 * cache around the copy so it can write straight into a PSRAM destination. */
extern "C" int spi_flash_read(uint32_t addr, void *dest, uint32_t size);
#define VELAPAW_MODEL_FLASH_OFFSET 0x600000u

/* The flash driver keeps its SPI transfer buffer on the *caller's* stack, and
 * the velapaw task stack is PSRAM (unwritable while the read suspends the
 * cache). So run the read on a short-lived thread whose stack is this static
 * internal-RAM (.bss) buffer. */
static uint8_t g_flash_rd_stack[8192];
struct velapaw_flash_rd
{
  uint32_t off;
  void    *dst;
  uint32_t len;
  int      rc;
};
static void *velapaw_flash_rd_thread(void *arg)
{
  struct velapaw_flash_rd *r = (struct velapaw_flash_rd *)arg;
  int sv;
  printf("tflm: read-thread stack@%p (3fc=internal)\n", (void *)&sv);
  fflush(stdout);
  r->rc = spi_flash_read(r->off, r->dst, r->len);
  return NULL;
}

/* Read the model straight from raw flash into the PSRAM buffer -- the driver
 * chunks internally and handles the PSRAM cache toggling itself. */
static uint8_t *model_buf = nullptr;
if (model_buf == nullptr)
  {
    uint32_t len = (uint32_t)g_velapaw_model_data_size;
    model_buf = (uint8_t *)kmm_memalign(16, len);   /* PSRAM */
    if (model_buf == nullptr)
      {
        MicroPrintf("velapaw/tflm: model buf alloc %u B failed", len);
        return -1;
      }
    printf("tflm: spi_flash_read @0x%06x -> PSRAM %p len=%u (on internal-stack thread)...\n",
           VELAPAW_MODEL_FLASH_OFFSET, (void *)model_buf, (unsigned)len);
    fflush(stdout);
    struct velapaw_flash_rd r =
      { VELAPAW_MODEL_FLASH_OFFSET, model_buf, len, -1 };
    pthread_attr_t attr;
    pthread_attr_init(&attr);
    pthread_attr_setstack(&attr, g_flash_rd_stack, sizeof(g_flash_rd_stack));
    pthread_t tid;
    int pr = pthread_create(&tid, &attr, velapaw_flash_rd_thread, &r);
    if (pr != 0)
      {
        MicroPrintf("velapaw/tflm: flash read thread create failed (%d)", pr);
        return -1;
      }
    pthread_join(tid, NULL);
    int rc = r.rc;
    printf("tflm: flash read rc=%d, buf[0..7]=%02x %02x %02x %02x %02x %02x %02x %02x (want ..54 46 4c 33)\n",
           rc, model_buf[0], model_buf[1], model_buf[2], model_buf[3],
           model_buf[4], model_buf[5], model_buf[6], model_buf[7]);
    fflush(stdout);
    if (rc != 0)
      {
        MicroPrintf("velapaw/tflm: flash read failed (%d)", rc);
        return -1;
      }
  }
/* Verify the read against the host checksum (sum32=0x0a5e8f6d) and isolate
 * exactly where init dies. */
{
  uint32_t s = 0;
  uint32_t n = (uint32_t)g_velapaw_model_data_size;
  for (uint32_t i = 0; i < n; i++) s += model_buf[i];
  printf("tflm: sum32=%08x (want 0a5e8f6d) b32=%02x(14) b1k=%02x(00) b500k=%02x(f1) blast=%02x(03)\n",
         (unsigned)s, model_buf[32], model_buf[1000], model_buf[500000],
         model_buf[n - 1]); fflush(stdout);
}
printf("tflm: GetModel...\n"); fflush(stdout);
g_model = tflite::GetModel(model_buf);
printf("tflm: GetModel=%p, reading version...\n", (const void *)g_model);
fflush(stdout);
{
  unsigned ver = (unsigned)g_model->version();
  printf("tflm: model version=%u\n", ver); fflush(stdout);
}

